public class MediaInsightsPipelineFactory(string resourceName = null, Action<Humidifier.Chime.MediaInsightsPipeline> factoryAction = null) : ResourceFactory<Humidifier.Chime.MediaInsightsPipeline>(resourceName)
{

    internal InnerMediaInsightsPipelineKinesisVideoStreamSourceRuntimeConfigurationFactory KinesisVideoStreamSourceRuntimeConfigurationFactory { get; set; }

    internal InnerMediaInsightsPipelineS3RecordingSinkRuntimeConfigurationFactory S3RecordingSinkRuntimeConfigurationFactory { get; set; }

    internal InnerMediaInsightsPipelineKinesisVideoStreamRecordingSourceRuntimeConfigurationFactory KinesisVideoStreamRecordingSourceRuntimeConfigurationFactory { get; set; }

    protected override Humidifier.Chime.MediaInsightsPipeline Create()
    {
        var mediaInsightsPipelineResult = CreateMediaInsightsPipeline();
        factoryAction?.Invoke(mediaInsightsPipelineResult);

        return mediaInsightsPipelineResult;
    }

    private Humidifier.Chime.MediaInsightsPipeline CreateMediaInsightsPipeline()
    {
        var mediaInsightsPipelineResult = new Humidifier.Chime.MediaInsightsPipeline
        {
            GivenName = InputResourceName,
        };

        return mediaInsightsPipelineResult;
    }
    public override void CreateChildren(Humidifier.Chime.MediaInsightsPipeline result)
    {
        base.CreateChildren(result);

        result.KinesisVideoStreamSourceRuntimeConfiguration ??= KinesisVideoStreamSourceRuntimeConfigurationFactory?.Build();
        result.S3RecordingSinkRuntimeConfiguration ??= S3RecordingSinkRuntimeConfigurationFactory?.Build();
        result.KinesisVideoStreamRecordingSourceRuntimeConfiguration ??= KinesisVideoStreamRecordingSourceRuntimeConfigurationFactory?.Build();
    }

} // End Of Class

